  #chat-modal {
    width: 50%;
  }
</style>
```

JavaScript:

```javascript
// Function to create chat message HTML
function createChatMessage(message, isUser) {
  const messageClass = isUser ? "chat-message sent" : "chat-message received";
  return `
    <div class="${messageClass}">
      <p>${message}</p>
    </div>
  `;
}

// Example chat messages
const humanMessages = ["Hi, how are you?", "Can you tell me more about your product?"];
const botMessages = ["I'm doing great, thanks for asking! ", "Sure, here's some information about our product."];

// Show modal with chat history
const showChatModal = () => {
  const modal = document.getElementById("chat-modal");
  const chatHistory = document.getElementById("chat-history");

  // Clear previous chat history
  chatHistory.innerHTML = "";

  // Add chat messages to modal
  for (let I = 0; I < humanMessages.length; i++) {
    const humanMessage = createChatMessage(humanMessages[i], true);
    chatHistory.innerHTML += humanMessage;

    const botMessage = createChatMessage(botMessages[i], false);
    chatHistory.innerHTML += botMessage;
  }

  // Open modal
  modal.classList.add("modal-show");
};

// Trigger modal when button is clicked
const modalButton = document.getElementById("show-modal");
modalButton.addEventListener("click", showChatModal);
```

